-- Prevent an author from moving or re-identifying a persisted message.
create or replace function public.guard_message_immutable_fields() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.sender_id is distinct from old.sender_id or new.created_at is distinct from old.created_at or new.client_event_id is distinct from old.client_event_id or new.room_id is distinct from old.room_id or new.thread_id is distinct from old.thread_id then raise exception 'Message identity and destination are immutable'; end if; return new; end $$;
drop trigger if exists guard_message_immutable_fields_trigger on public.messages; create trigger guard_message_immutable_fields_trigger before update on public.messages for each row execute procedure public.guard_message_immutable_fields();
